// Package hypertext serves the survey pages. Its routes are generated by
// muxt from pages.gohtml. Two kinds of form are made by jsonhandler.Handle:
// the one authors use to write a survey, from a fixed schema, and the one
// respondents fill in, from a schema built out of the survey they open.
// Each page is one method that answers both the GET and the POST of its
// form, because Handle keeps all the form's state in the request.
package hypertext

import (
	"context"
	"crypto/sha256"
	"encoding/json/jsontext"
	"errors"
	"fmt"
	"html/template"
	"log/slog"
	"net/http"
	"sync"

	"github.com/crhntr/jsonschema"
	"github.com/crhntr/jsonschema/jsonhandler"

	"github.com/crhntr/jsonschema/examples/surveys/internal/store"
	"github.com/crhntr/jsonschema/examples/surveys/internal/survey"
	"github.com/crhntr/jsonschema/examples/surveys/schema"
)

//go:generate go tool muxt generate --use-receiver-type=Server --output-htmx

// Server is the routes receiver.
type Server struct {
	store *store.Store
	log   *slog.Logger

	// definition is the schema of the form authors write surveys with.
	definition *jsonschema.Schema

	// answers holds the form for each survey definition seen lately, by
	// the hash of the definition, so a busy survey does not rebuild its
	// schema for every respondent.
	mu      sync.Mutex
	answers map[[sha256.Size]byte]*answerForm
}

// answerForm is what a survey needs to be taken: its definition and the
// schema of its answers.
type answerForm struct {
	def    survey.Definition
	schema *jsonschema.Schema
}

// maxCached is how many answer forms are kept before the cache starts over.
const maxCached = 256

// New returns a Server keeping its surveys in s.
func New(ctx context.Context, s *store.Store, log *slog.Logger) (*Server, error) {
	def, err := jsonhandler.ParseSchema(ctx, schema.Definition())
	if err != nil {
		return nil, fmt.Errorf("survey form: %w", err)
	}
	return &Server{store: s, log: log, definition: def, answers: map[[sha256.Size]byte]*answerForm{}}, nil
}

// Routes registers the pages and the form stylesheet.
func Routes(mux *http.ServeMux, s *Server) TemplateRoutePaths {
	paths := TemplateRoutes(mux, s)
	mux.HandleFunc("GET /jsonform.css", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
		_, _ = w.Write(jsonhandler.Stylesheet())
	})
	return paths
}

// Layout is what every page's frame shows. Public pages, which
// respondents see, have no navigation to the authors' pages.
type Layout struct {
	Title  string
	Public bool
}

// FormPage is a page that is mostly a form.
type FormPage struct {
	Layout
	Heading     string
	Description string
	Form        template.HTML
}

// FormResponse is the answer to a request for a form: the page with the
// form on it (a first view, an edit, or errors), or where to go once it
// was saved.
type FormResponse struct {
	FormPage
	Location string
	status   int
}

// StatusCode is 422 for a form with errors, otherwise 200.
func (r FormResponse) StatusCode() int {
	if r.status == 0 {
		return http.StatusOK
	}
	return r.status
}

// live is the options of a form that checks itself as it is typed, at the
// URL of the page followed by /validate.
func live(r *http.Request, o jsonhandler.Options) *jsonhandler.Options {
	o.ValidateAction = r.URL.Path + "/validate"
	return &o
}

// Home lists the surveys.
type Home struct {
	Layout
	Surveys []store.Entry
}

// Home shows every survey, with links to take it, see its results, and
// edit it.
func (s *Server) Home(_ context.Context) (Home, error) {
	entries, err := s.store.List()
	if err != nil {
		return Home{}, s.fail(err)
	}
	return Home{Layout: Layout{Title: "Surveys"}, Surveys: entries}, nil
}

// -- Writing a survey -------------------------------------------------

var definitionOptions = jsonhandler.Options{ID: "survey", SubmitLabel: "Save survey", Outline: true}

// NewSurvey serves the form for a new survey, and receives its post.
func (s *Server) NewSurvey(request *http.Request) (FormResponse, error) {
	return s.writeSurvey(request, "")
}

// EditSurvey serves the form for an existing survey, and receives its post.
func (s *Server) EditSurvey(request *http.Request, name string) (FormResponse, error) {
	return s.writeSurvey(request, name)
}

// writeSurvey is the page for writing a survey: name is "" for a new one.
func (s *Server) writeSurvey(r *http.Request, name string) (FormResponse, error) {
	var current jsontext.Value
	heading := "New survey"
	if name != "" {
		var err error
		if current, err = s.store.Get(name); err != nil {
			return FormResponse{}, s.fail(err)
		}
		heading = "Edit survey"
	}
	f, err := jsonhandler.Handle(r, s.definition, current, live(r, definitionOptions))
	if err != nil {
		return FormResponse{}, s.fail(err)
	}
	if f.Valid {
		saved, err := s.saveDefinition(name, f.Value)
		if err == nil {
			return FormResponse{Location: "/surveys/" + saved + "/results"}, nil
		}
		f.Reject(s.fail(err))
	}
	html, err := f.HTML()
	if err != nil {
		return FormResponse{}, s.fail(err)
	}
	return FormResponse{FormPage: FormPage{Layout: Layout{Title: heading}, Heading: heading, Form: html}, status: f.StatusCode()}, nil
}

// ValidateSurvey checks a survey's form as it is typed.
func (s *Server) ValidateSurvey(request *http.Request) (template.HTML, error) {
	html, err := jsonhandler.ValidateHTML(request, s.definition, nil, &definitionOptions)
	return html, s.fail(err)
}

// DeleteSurvey removes a survey and its responses.
func (s *Server) DeleteSurvey(name string) error {
	return s.fail(s.store.Delete(name))
}

// saveDefinition stores a valid definition, after checking that a form can
// be made from it, and returns the survey's name. name is "" for a new
// survey, which is named after its title.
func (s *Server) saveDefinition(name string, v jsontext.Value) (string, error) {
	def, err := survey.Parse(v)
	if err != nil {
		return "", err
	}
	if _, err := def.Schema(); err != nil {
		return "", message("These questions cannot make a form: " + err.Error() + ".")
	}
	if name == "" {
		if name = survey.Slug(def.Title); name == "" {
			return "", message("The title needs some letters or digits, to make a web address from.")
		}
		err = s.store.Create(name, v)
	} else {
		err = s.store.Update(name, v)
	}
	if errors.Is(err, store.ErrExists) {
		return "", message(fmt.Sprintf("There is already a survey called %q. Give this one a different title.", name))
	}
	return name, err
}

// -- Taking a survey --------------------------------------------------

// answerFormNamed returns the form for the survey called name.
func (s *Server) answerFormNamed(ctx context.Context, name string) (*answerForm, error) {
	raw, err := s.store.Get(name)
	if err != nil {
		return nil, s.fail(err)
	}
	key := sha256.Sum256(raw)
	s.mu.Lock()
	cached, ok := s.answers[key]
	s.mu.Unlock()
	if ok {
		return cached, nil
	}
	made, err := compile(ctx, raw)
	if err != nil {
		return nil, s.fail(fmt.Errorf("survey %s: %w", name, err))
	}
	s.mu.Lock()
	if len(s.answers) >= maxCached {
		clear(s.answers)
	}
	s.answers[key] = made
	s.mu.Unlock()
	return made, nil
}

// compile builds the schema of a survey's answers.
func compile(ctx context.Context, raw jsontext.Value) (*answerForm, error) {
	def, err := survey.Parse(raw)
	if err != nil {
		return nil, err
	}
	doc, err := def.Schema()
	if err != nil {
		return nil, err
	}
	s, err := jsonhandler.ParseSchema(ctx, doc)
	if err != nil {
		return nil, err
	}
	return &answerForm{def: def, schema: s}, nil
}

// answerOptions: a respondent has no use for raw JSON.
var answerOptions = jsonhandler.Options{ID: "answers", SubmitLabel: "Send answers", NoJSON: true}

// Answer serves a survey's form, and receives its post. Complete answers
// are recorded and the respondent is sent on; anything else is the form
// again, with what is wrong.
func (s *Server) Answer(request *http.Request, name string) (FormResponse, error) {
	a, err := s.answerFormNamed(request.Context(), name)
	if err != nil {
		return FormResponse{}, err
	}
	f, err := jsonhandler.Handle(request, a.schema, nil, live(request, answerOptions))
	if err != nil {
		return FormResponse{}, s.fail(err)
	}
	if f.Valid {
		err := s.store.AddResponse(name, f.Value)
		if err == nil {
			return FormResponse{Location: "/s/" + name + "/thanks"}, nil
		}
		f.Reject(s.fail(err))
	}
	html, err := f.HTML()
	if err != nil {
		return FormResponse{}, s.fail(err)
	}
	page := FormPage{
		Layout:      Layout{Title: a.def.Title, Public: true},
		Heading:     a.def.Title,
		Description: a.def.Description,
		Form:        html,
	}
	return FormResponse{FormPage: page, status: f.StatusCode()}, nil
}

// ValidateAnswers checks the answers as they are typed.
func (s *Server) ValidateAnswers(request *http.Request, name string) (template.HTML, error) {
	a, err := s.answerFormNamed(request.Context(), name)
	if err != nil {
		return "", err
	}
	html, err := jsonhandler.ValidateHTML(request, a.schema, nil, &answerOptions)
	return html, s.fail(err)
}

// Thanks is shown after answers were sent.
type Thanks struct {
	Layout
	Name  string
	Title string
}

// Thanks thanks a respondent.
func (s *Server) Thanks(_ context.Context, name string) (Thanks, error) {
	raw, err := s.store.Get(name)
	if err != nil {
		return Thanks{}, s.fail(err)
	}
	def, err := survey.Parse(raw)
	if err != nil {
		return Thanks{}, s.fail(err)
	}
	return Thanks{Layout: Layout{Title: "Thank you", Public: true}, Name: name, Title: def.Title}, nil
}

// -- Results ----------------------------------------------------------

// ResultsPage summarizes the answers to a survey.
type ResultsPage struct {
	Layout
	Name      string
	Title     string
	Responses int
	Results   []survey.Result
}

// Results shows how people answered each question.
func (s *Server) Results(_ context.Context, name string) (ResultsPage, error) {
	raw, err := s.store.Get(name)
	if err != nil {
		return ResultsPage{}, s.fail(err)
	}
	def, err := survey.Parse(raw)
	if err != nil {
		return ResultsPage{}, s.fail(err)
	}
	responses, err := s.store.Responses(name)
	if err != nil {
		return ResultsPage{}, s.fail(err)
	}
	return ResultsPage{
		Layout:    Layout{Title: def.Title + " results"},
		Name:      name,
		Title:     def.Title,
		Responses: len(responses),
		Results:   def.Summarize(responses),
	}, nil
}
